/*******************************************************************************
 * Drop and recreate TRANSACTIONS with an identity primary key.
 *
 * Purpose:
 *   Existing schema has TRANSACTIONS.TRANSACTION_NO as INTEGER NOT NULL.
 *   This script rebuilds the table as:
 *     INTEGER GENERATED BY DEFAULT AS IDENTITY (START WITH 1) NOT NULL
 *
 * Notes:
 *   - This script does not preserve or move data.
 *   - Run this only when TRANSACTIONS can be dropped empty, or when another
 *     process such as Pump_ASA_FB will reload the data afterward.
 *   - Back up the database before running.
 ******************************************************************************/

SET TERM ^ ;

/* Remove stored routine dependencies that can block DROP TABLE TRANSACTIONS. */
CREATE OR ALTER FUNCTION FN_TRAN_WITH_LATE_PAYMENT (
  TRANSACTION_NO Integer,
  MONS Integer DEFAULT 1)
 RETURNS SmallInt
SQL SECURITY INVOKER
AS
BEGIN
  RETURN NULL;
END^

CREATE OR ALTER PROCEDURE REP_CUSTOMER_WITH_LATE_PAYMENTS (
  MONS Integer DEFAULT 1)
 returns (
  TRANSACTION_NO Integer,
  TRAN_TICKET_NO VarChar(30),
  TRAN_DATE Timestamp,
  LATE_PAYMENT SmallInt,
  CUST_NO Integer,
  CUST_LAST VarChar(35),
  CUST_FIRST VarChar(35),
  CUST_MID Char(1),
  CUST_PH_CELL VarChar(14),
  CUST_PH_HOME VarChar(14),
  CUST_PH_BUSINESS VarChar(14),
  TRAN_PAWN_AMOUNT Double Precision)
SQL SECURITY INVOKER
AS
BEGIN
  EXIT;
END^

CREATE OR ALTER PROCEDURE SPU_CALC_UNIT_COST_FROM_WEIGHT (
  TRANSACTION_NO Integer)
SQL SECURITY INVOKER
AS
BEGIN
  EXIT;
END^

EXECUTE BLOCK AS
BEGIN
  IF (EXISTS(
    SELECT 1
    FROM RDB$RELATION_CONSTRAINTS
    WHERE TRIM(RDB$CONSTRAINT_NAME) = 'FK_INVENTORY_ITEMS_TRANSACTIONS'
  )) THEN
    EXECUTE STATEMENT 'ALTER TABLE INVENTORY_ITEMS DROP CONSTRAINT FK_INVENTORY_ITEMS_TRANSACTIONS';

  IF (EXISTS(
    SELECT 1
    FROM RDB$RELATION_CONSTRAINTS
    WHERE TRIM(RDB$CONSTRAINT_NAME) = 'FK_PAYMENTS_TRANSACTIONS'
  )) THEN
    EXECUTE STATEMENT 'ALTER TABLE PAYMENTS DROP CONSTRAINT FK_PAYMENTS_TRANSACTIONS';

  IF (EXISTS(
    SELECT 1
    FROM RDB$RELATION_CONSTRAINTS
    WHERE TRIM(RDB$CONSTRAINT_NAME) = 'FK_TRANSACTIONS_CUSTOMER'
  )) THEN
    EXECUTE STATEMENT 'ALTER TABLE TRANSACTIONS DROP CONSTRAINT FK_TRANSACTIONS_CUSTOMER';
END^

SET TERM ; ^

DROP TABLE TRANSACTIONS;

CREATE TABLE TRANSACTIONS
(
  TRANSACTION_NO                 INTEGER         GENERATED BY DEFAULT AS IDENTITY (START WITH 1) NOT NULL,
  CUST_NO                        INTEGER,
  TRAN_DATE                         DATE         DEFAULT CURRENT_DATE,
  TRAN_TICKET_NO                 VARCHAR(30),
  TRAN_COMMENT                      BLOB SUB_TYPE 1 SEGMENT SIZE 80,
  TRAN_MATURITY                     DATE,
  TRAN_TYPE                         CHAR(1) DEFAULT 'P',
  TRAN_STATUS                       CHAR(1) DEFAULT 'A',
  TRAN_VOID_DATE               TIMESTAMP,
  TRAN_PAWN_AMOUNT      DOUBLE PRECISION,
  TRAN_INTEREST         DOUBLE PRECISION,
  PRINC_BALANCE         DOUBLE PRECISION,
  INTEREST_BALANCE      DOUBLE PRECISION,
  TRAN_TIME                         TIME         DEFAULT CURRENT_TIME,
  TRAN_CLOSE_REASON             SMALLINT         DEFAULT 0 NOT NULL,
  TRAN_SALES_TAX        DOUBLE PRECISION,
  PRIMARY KEY (TRANSACTION_NO)
);

COMMENT ON COLUMN TRANSACTIONS.TRAN_STATUS IS 'A-Active
V-Void';

COMMENT ON COLUMN TRANSACTIONS.TRAN_CLOSE_REASON IS '0-Open 1-Void 2-Redeemed 3-Defaulted 4-Mix 0-Open 1-Void 2-Redeemed 3-Defaulted 4-Mix Default/Redeem';

CREATE ASC INDEX TRANSACTIONS_IDX1 ON TRANSACTIONS (CUST_NO, TRAN_DATE, TRAN_TICKET_NO);

/* Add these after Pump_ASA_FB reloads TRANSACTIONS, INVENTORY_ITEMS, and PAYMENTS.
 * See PawnPro_FB5_AddTransactionsForeignKeys.sql.
 */

ALTER TABLE TRANSACTIONS ADD CONSTRAINT FK_TRANSACTIONS_CUSTOMER
  FOREIGN KEY (CUST_NO) REFERENCES CUSTOMER
  (CUST_NO)
  ON DELETE CASCADE
  ON UPDATE NO ACTION;

SET TERM ^ ;

CREATE OR ALTER FUNCTION FN_TRAN_WITH_LATE_PAYMENT (
  TRANSACTION_NO Integer,
  MONS Integer DEFAULT 1)
 RETURNS SmallInt
SQL SECURITY INVOKER
AS
DECLARE VARIABLE PAWN_DATE     DATE;
  DECLARE VARIABLE LAST_PAY_DAY  DATE;
  DECLARE VARIABLE CMP_DATE      DATE;
BEGIN
  SELECT TRAN_DATE       FROM TRANSACTIONS WHERE TRANSACTION_NO = :TRANSACTION_NO INTO :PAWN_DATE;
  SELECT MAX(PAY_DATE)   FROM PAYMENTS     WHERE TRANSACTION_NO = :TRANSACTION_NO INTO :LAST_PAY_DAY;

  CMP_DATE = COALESCE(:LAST_PAY_DAY, :PAWN_DATE);
  IF (:CMP_DATE IS NULL) THEN
    RETURN 0;

  IF (ABS(DATEDIFF(MONTH FROM :CMP_DATE TO CURRENT_DATE)) > :MONS) THEN
    RETURN 1;
  ELSE
    RETURN 0;
END^

CREATE OR ALTER PROCEDURE REP_CUSTOMER_WITH_LATE_PAYMENTS (
  MONS Integer DEFAULT 1)
 returns (
  TRANSACTION_NO Integer,
  TRAN_TICKET_NO VarChar(30),
  TRAN_DATE Timestamp,
  LATE_PAYMENT SmallInt,
  CUST_NO Integer,
  CUST_LAST VarChar(35),
  CUST_FIRST VarChar(35),
  CUST_MID Char(1),
  CUST_PH_CELL VarChar(14),
  CUST_PH_HOME VarChar(14),
  CUST_PH_BUSINESS VarChar(14),
  TRAN_PAWN_AMOUNT Double Precision)
SQL SECURITY INVOKER
AS
BEGIN
  FOR
    SELECT FIRST 1000
      T2.TRANSACTION_NO,
      T2.TRAN_TICKET_NO,
      CAST(T2.TRAN_DATE AS TIMESTAMP),
      1,
      T1.CUST_NO,
      T1.CUST_LAST,
      T1.CUST_FIRST,
      T1.CUST_MID,
      T1.CUST_PH_CELL,
      T1.CUST_PH_HOME,
      T1.CUST_PH_BUSINESS,
      T2.TRAN_PAWN_AMOUNT
    FROM CUSTOMER T1
      JOIN TRANSACTIONS T2 ON T1.CUST_NO = T2.CUST_NO
    WHERE T2.TRAN_TYPE   = 'P'
      AND T2.TRAN_STATUS = 'A'
      AND FN_TRAN_WITH_LATE_PAYMENT(T2.TRANSACTION_NO, :MONS) = 1
    ORDER BY T1.CUST_FIRST ASC, T1.CUST_LAST ASC, T1.CUST_NO ASC
    INTO
      :TRANSACTION_NO,
      :TRAN_TICKET_NO,
      :TRAN_DATE,
      :LATE_PAYMENT,
      :CUST_NO,
      :CUST_LAST,
      :CUST_FIRST,
      :CUST_MID,
      :CUST_PH_CELL,
      :CUST_PH_HOME,
      :CUST_PH_BUSINESS,
      :TRAN_PAWN_AMOUNT
  DO
    SUSPEND;
END^

CREATE OR ALTER PROCEDURE SPU_CALC_UNIT_COST_FROM_WEIGHT (
  TRANSACTION_NO Integer)
SQL SECURITY INVOKER
AS
DECLARE VARIABLE TOTAL_WEIGHT      DOUBLE PRECISION;
  DECLARE VARIABLE TOTAL_AMOUNT      DOUBLE PRECISION;
  DECLARE VARIABLE DOLLAR_PER_WEIGHT DOUBLE PRECISION;
BEGIN
  SELECT SUM(WEIGHT)       FROM INVENTORY_ITEMS WHERE TRANSACTION_NO = :TRANSACTION_NO INTO :TOTAL_WEIGHT;
  SELECT TRAN_PAWN_AMOUNT  FROM TRANSACTIONS    WHERE TRANSACTION_NO = :TRANSACTION_NO INTO :TOTAL_AMOUNT;

  DOLLAR_PER_WEIGHT = :TOTAL_AMOUNT / :TOTAL_WEIGHT;

  UPDATE INVENTORY_ITEMS
    SET UNIT_COST = :DOLLAR_PER_WEIGHT * WEIGHT
    WHERE TRANSACTION_NO = :TRANSACTION_NO;
END^

SET TERM ; ^

COMMIT;
